-- Role baselines for the reconciled codes (administrator: all; user: all but
-- the protected template-management key; viewer: VIEW operations).
INSERT INTO role_permissions (role_id, permission_id)
SELECT r.role_id, p.permission_id FROM roles r CROSS JOIN permissions p
WHERE r.role_code = 'ROLE_ADMINISTRATOR' AND r.is_active = true AND p.is_active = true AND p.permission_code IN ('ACC.CUSTOMER_LEDGER.VIEW','ACC.FINANCIAL_ANALYSIS.VIEW','ACC.FINANCIAL_ANALYSIS.AI','ACC.FINANCIAL_STATEMENTS.VIEW','AI.ASSISTANT','AI.FINANCIAL_ANALYSIS','AI.INVENTORY_ANALYSIS','AI.SALES_ANALYSIS','AI.FORECAST','AUDIT.SECURITY_EVENTS.VIEW','BANK.RECONCILIATION.VIEW','BANK.RECONCILIATION.EXECUTE','VCH.PAYMENT_METHOD.MANAGE','SYS.PERMISSION_TEMPLATES.MANAGE') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions (role_id, permission_id)
SELECT r.role_id, p.permission_id FROM roles r CROSS JOIN permissions p
WHERE r.role_code = 'ROLE_USER' AND r.is_active = true AND p.is_active = true AND p.permission_code IN ('ACC.CUSTOMER_LEDGER.VIEW','ACC.FINANCIAL_ANALYSIS.VIEW','ACC.FINANCIAL_ANALYSIS.AI','ACC.FINANCIAL_STATEMENTS.VIEW','AI.ASSISTANT','AI.FINANCIAL_ANALYSIS','AI.INVENTORY_ANALYSIS','AI.SALES_ANALYSIS','AI.FORECAST','AUDIT.SECURITY_EVENTS.VIEW','BANK.RECONCILIATION.VIEW','BANK.RECONCILIATION.EXECUTE','VCH.PAYMENT_METHOD.MANAGE') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions (role_id, permission_id)
SELECT r.role_id, p.permission_id FROM roles r CROSS JOIN permissions p
WHERE r.role_code = 'ROLE_VIEWER' AND r.is_active = true AND p.is_active = true AND p.permission_code IN ('ACC.CUSTOMER_LEDGER.VIEW','ACC.FINANCIAL_ANALYSIS.VIEW','ACC.FINANCIAL_STATEMENTS.VIEW','AI.ASSISTANT','AI.FINANCIAL_ANALYSIS','AI.INVENTORY_ANALYSIS','AI.SALES_ANALYSIS','AI.FORECAST','AUDIT.SECURITY_EVENTS.VIEW','BANK.RECONCILIATION.VIEW') ON CONFLICT DO NOTHING;

