-- ---- Template tables ----------------------------------------------------------
CREATE TABLE IF NOT EXISTS permission_templates (
    template_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    company_id uuid NULL REFERENCES companies(company_id),
    template_code varchar(100) NOT NULL,
    name_en varchar(200) NOT NULL,
    name_ar varchar(200) NOT NULL,
    description text NULL,
    is_system boolean NOT NULL DEFAULT false,
    is_active boolean NOT NULL DEFAULT true,
    is_deleted boolean NOT NULL DEFAULT false,
    created_by varchar(250) NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_by varchar(250) NULL,
    updated_at timestamptz NULL,
    UNIQUE(company_id, template_code)
);
CREATE TABLE IF NOT EXISTS permission_template_grants (
    template_id bigint NOT NULL REFERENCES permission_templates(template_id),
    permission_id bigint NOT NULL REFERENCES permissions(permission_id),
    PRIMARY KEY (template_id, permission_id)
);
CREATE TABLE IF NOT EXISTS user_permission_templates (
    user_id uuid NOT NULL REFERENCES users(user_id),
    template_id bigint NOT NULL REFERENCES permission_templates(template_id),
    assigned_by varchar(250) NULL,
    assigned_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, template_id)
);
CREATE INDEX IF NOT EXISTS ix_user_permission_templates_template ON user_permission_templates(template_id);
CREATE INDEX IF NOT EXISTS ix_permission_templates_company ON permission_templates(company_id, template_code);

-- ---- Seeded global system templates ------------------------------------------
INSERT INTO permission_templates(company_id, template_code, name_en, name_ar, description, is_system, is_active, is_deleted, created_by, updated_by)
SELECT NULL, 'SYS_READ_ONLY', 'Read Only', 'Read Only', 'Every VIEW operation plus report printing. Seeded system template (migration 125); copy it to adapt.', TRUE, TRUE, FALSE, 'system', 'system'
WHERE NOT EXISTS (SELECT 1 FROM permission_templates WHERE company_id IS NULL AND template_code = 'SYS_READ_ONLY');
INSERT INTO permission_template_grants (template_id, permission_id)
SELECT t.template_id, p.permission_id FROM permission_templates t CROSS JOIN permissions p
WHERE t.company_id IS NULL AND t.template_code = 'SYS_READ_ONLY' AND p.is_active = TRUE AND (p.operation_code = 'VIEW' OR p.permission_code = 'REPORT.PRINT') ON CONFLICT DO NOTHING;
INSERT INTO permission_templates(company_id, template_code, name_en, name_ar, description, is_system, is_active, is_deleted, created_by, updated_by)
SELECT NULL, 'SYS_CASHIER', 'Cashier', 'Cashier', 'The POS family, POS document rights and cash-sale creation. Seeded system template (migration 125); copy it to adapt.', TRUE, TRUE, FALSE, 'system', 'system'
WHERE NOT EXISTS (SELECT 1 FROM permission_templates WHERE company_id IS NULL AND template_code = 'SYS_CASHIER');
INSERT INTO permission_template_grants (template_id, permission_id)
SELECT t.template_id, p.permission_id FROM permission_templates t CROSS JOIN permissions p
WHERE t.company_id IS NULL AND t.template_code = 'SYS_CASHIER' AND p.is_active = TRUE AND (p.group_code = 'POS' OR p.permission_code = 'SALES.CASH.CREATE' OR p.permission_code LIKE 'DOC.POS.%') ON CONFLICT DO NOTHING;
INSERT INTO permission_templates(company_id, template_code, name_en, name_ar, description, is_system, is_active, is_deleted, created_by, updated_by)
SELECT NULL, 'SYS_ACCOUNTANT', 'Accountant', 'Accountant', 'Accounting, vouchers and banking in full, plus report view/print/export. Seeded system template (migration 125); copy it to adapt.', TRUE, TRUE, FALSE, 'system', 'system'
WHERE NOT EXISTS (SELECT 1 FROM permission_templates WHERE company_id IS NULL AND template_code = 'SYS_ACCOUNTANT');
INSERT INTO permission_template_grants (template_id, permission_id)
SELECT t.template_id, p.permission_id FROM permission_templates t CROSS JOIN permissions p
WHERE t.company_id IS NULL AND t.template_code = 'SYS_ACCOUNTANT' AND p.is_active = TRUE AND (p.group_code IN ('ACCOUNTING','VOUCHERS','BANKING') OR p.permission_code IN ('REPORT.VIEW','REPORT.PRINT','REPORT.EXPORT')) ON CONFLICT DO NOTHING;
